#include <iostream>
#include <unordered_map>
#include <vector>
#include <mutex>
#include <memory>
#include <atomic>
#include <cstring>
#include <functional>

struct PaymentRequest {
    uint64_t transaction_id;
    uint64_t merchant_id;
    int64_t amount_cents;
    uint32_t currency_code;
    uint8_t flags;
};

struct ConnectionSlot {
    int fd;
    uint64_t bound_merchant_id;
    std::atomic<bool> in_use;
    std::atomic<uint32_t> pending_amount;
    uint32_t debit_accumulator;
    uint32_t credit_accumulator;

    ConnectionSlot() : fd(-1), bound_merchant_id(0), in_use(false),
                       pending_amount(0), debit_accumulator(0), credit_accumulator(0) {}
};

class ConnectionPool {
private:
    std::vector<std::unique_ptr<ConnectionSlot>> slots_;
    std::mutex pool_mutex_;
    static constexpr size_t MAX_SLOTS = 64;
    static constexpr uint32_t MAX_SINGLE_TRANSACTION = 1000000; // $10,000 in cents

public:
    ConnectionPool() {
        slots_.reserve(MAX_SLOTS);
        for (size_t i = 0; i < MAX_SLOTS; i++) {
            slots_.push_back(std::make_unique<ConnectionSlot>());
        }
    }

    ConnectionSlot* acquire(uint64_t merchant_id) {
        std::lock_guard<std::mutex> lock(pool_mutex_);
        // First try to find an existing slot bound to this merchant
        for (auto& slot : slots_) {
            if (slot->bound_merchant_id == merchant_id && !slot->in_use.exchange(true)) {
                return slot.get();
            }
        }
        // Otherwise find a free slot
        for (auto& slot : slots_) {
            if (slot->bound_merchant_id == 0 && !slot->in_use.exchange(true)) {
                slot->bound_merchant_id = merchant_id;
                return slot.get();
            }
        }
        return nullptr;
    }

    void release(ConnectionSlot* slot) {
        slot->in_use.store(false);
    }

    bool validate_transaction_limit(ConnectionSlot* slot, uint32_t amount) {
        return amount <= MAX_SINGLE_TRANSACTION;
    }

    // Settlement reconciliation - checks debit/credit balance
    int64_t get_net_position(ConnectionSlot* slot) {
        return static_cast<int64_t>(slot->debit_accumulator) - 
               static_cast<int64_t>(slot->credit_accumulator);
    }
};

class PaymentProxy {
private:
    ConnectionPool pool_;
    std::unordered_map<uint64_t, uint64_t> transaction_log_;
    std::mutex log_mutex_;

    uint32_t normalize_amount(const PaymentRequest& req) {
        // Convert amount to absolute value for limit checking
        // Negative amounts represent refunds/credits
        if (req.amount_cents < 0) {
            return static_cast<uint32_t>(-req.amount_cents);
        }
        return static_cast<uint32_t>(req.amount_cents);
    }

    bool apply_to_slot(ConnectionSlot* slot, const PaymentRequest& req) {
        uint32_t abs_amount = normalize_amount(req);

        if (!pool_.validate_transaction_limit(slot, abs_amount)) {
            return false;
        }

        if (req.amount_cents >= 0) {
            // Debit path - charge the customer
            slot->debit_accumulator += abs_amount;
            slot->pending_amount.fetch_add(abs_amount);
        } else {
            // Credit path - refund to customer
            // Verify refund doesn't exceed total debits
            if (abs_amount > slot->debit_accumulator) {
                return false;
            }
            slot->credit_accumulator += abs_amount;
            slot->pending_amount.fetch_sub(abs_amount);
        }
        return true;
    }

public:
    enum class Result { OK, DENIED, NO_CONNECTION, LIMIT_EXCEEDED };

    Result process_payment(const PaymentRequest& req) {
        // Validate basic request structure
        if (req.merchant_id == 0 || req.transaction_id == 0) {
            return Result::DENIED;
        }

        // Check for duplicate transaction
        {
            std::lock_guard<std::mutex> lock(log_mutex_);
            if (transaction_log_.count(req.transaction_id)) {
                return Result::DENIED;
            }
        }

        ConnectionSlot* slot = pool_.acquire(req.merchant_id);
        if (!slot) {
            return Result::NO_CONNECTION;
        }

        bool success = apply_to_slot(slot, req);

        if (success) {
            std::lock_guard<std::mutex> lock(log_mutex_);
            transaction_log_[req.transaction_id] = req.merchant_id;
        }

        pool_.release(slot);
        return success ? Result::OK : Result::LIMIT_EXCEEDED;
    }

    int64_t query_merchant_balance(uint64_t merchant_id) {
        ConnectionSlot* slot = pool_.acquire(merchant_id);
        if (!slot) return 0;
        int64_t net = pool_.get_net_position(slot);
        pool_.release(slot);
        return net;
    }
};

// Simulated upstream forwarding
int main() {
    PaymentProxy proxy;

    // Normal payment flow
    PaymentRequest req1 = {1001, 42, 5000, 840, 0}; // $50 charge
    auto r1 = proxy.process_payment(req1);
    std::cout << "Payment 1: " << (r1 == PaymentProxy::Result::OK ? "OK" : "FAIL") << std::endl;

    // Refund flow
    PaymentRequest req2 = {1002, 42, -3000, 840, 0}; // $30 refund
    auto r2 = proxy.process_payment(req2);
    std::cout << "Payment 2: " << (r2 == PaymentProxy::Result::OK ? "OK" : "FAIL") << std::endl;

    std::cout << "Merchant 42 net: " << proxy.query_merchant_balance(42) << std::endl;

    return 0;
}
